p = Path("tests/test_core.py")
s = p.read_text()
s += '''\n\ndef test_normal_mode_ignores_min_pv_threshold():\n    now = datetime.now(timezone.utc)\n    start = now.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)\n    plan = EVPlanner(\n        PriceData(hours=[make_hour(start, price=0.50)]),\n        SolcastData(hours=[make_hour(start, pv=0.50)]),\n        PlannerSettings(0.50, start + timedelta(hours=1), 0.0, min_pv_kwh=1.0, planner_mode=\"Normaal laden\"),\n        DummyLogger(),\n    ).create_plan()\n    assert plan.complete\n    assert plan.free_energy_kwh > 0.49\n    assert plan.paid_energy_kwh == pytest.approx(0.0, abs=1e-6)\n\n\ndef _solar_plan(pv, rounding):\n    now = datetime.now(timezone.utc)\n    start = now.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)\n    return EVPlanner(\n        PriceData(hours=[make_hour(start, price=0.50)]),\n        SolcastData(hours=[make_hour(start, pv=pv)]),\n        PlannerSettings(1.0, start + timedelta(hours=1), 0.0, max_phase_switches=8, planner_mode=\"Alleen zonneladen\", pv_rounding=rounding),\n        DummyLogger(),\n    ).create_plan()\n\n\ndef test_solar_only_round_down():\n    decision = _solar_plan(2.10, \"Naar beneden — geen netenergie\").decisions[0]\n    assert decision.charge_current_a == 9\n    assert decision.paid_energy_kwh == pytest.approx(0.0, abs=1e-6)\n\n\ndef test_solar_only_round_up_allows_grid_supplement():\n    plan = _solar_plan(2.10, \"Naar boven — kleine netaanvulling toegestaan\")\n    decision = plan.decisions[0]\n    assert decision.charge_current_a == 10\n    assert decision.paid_energy_kwh > 0.0\n    assert plan.complete\n\n\ndef test_solar_only_ignores_max_price_for_rounding_supplement():\n    plan = _solar_plan(2.10, \"Naar boven — kleine netaanvulling toegestaan\")\n    assert plan.paid_energy_kwh > 0.0\n\n\ndef test_solar_only_below_six_ampere_does_not_charge():\n    plan = _solar_plan(1.00, \"Naar boven — kleine netaanvulling toegestaan\")\n    assert not plan.complete\n    assert plan.energy_planned_kwh == pytest.approx(0.0, abs=1e-6)\n'''
p.write_text(s)
